/* ============================================
   IMPORTS
   ============================================ */
@import "./tokens.css";
@import "./admin-tokens.css";

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ============================================
   BASE LAYER - Typography, Reset & Scrollbar
   ============================================ */
@layer base {
  /* Reset */
  * {
    box-sizing: border-box;
    padding: 0;
    margin: 0;
  }

  html,
  body {
    max-width: 100vw;
    overflow-x: hidden;
  }

  body {
    color: var(--foreground);
    background: var(--background);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  a {
    text-decoration: none;
  }

  /* Links inherit color only if no explicit color class is set */
  a:where(:not([class*="text-"])) {
    color: inherit;
  }

  /* Typography */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    @apply font-display font-bold;
    color: var(--text-primary);
  }

  h1 {
    @apply text-5xl md:text-6xl lg:text-7xl leading-tight;
  }

  h2 {
    @apply text-4xl md:text-5xl leading-tight;
  }

  h3 {
    @apply text-3xl md:text-4xl leading-snug;
  }

  h4 {
    @apply text-2xl md:text-3xl leading-snug;
  }

  h5 {
    @apply text-xl md:text-2xl leading-normal;
  }

  h6 {
    @apply text-lg md:text-xl leading-normal;
  }

  p {
    @apply text-base leading-relaxed;
    color: var(--text-secondary);
  }

  /* Scrollbar Styling */
  ::-webkit-scrollbar {
    @apply w-2;
  }

  ::-webkit-scrollbar-track {
    background: var(--surface);
  }

  ::-webkit-scrollbar-thumb {
    @apply rounded-full;
    background: var(--neo-accent);
  }

  ::-webkit-scrollbar-thumb:hover {
    background: var(--neo-accent);
    opacity: 0.8;
  }

  /* Force scrollbar on all elements that scroll */
  * {
    scrollbar-color: var(--neo-accent) var(--surface);
    scrollbar-width: thin;
  }

  /* Selection */
  ::selection {
    background: rgba(213, 255, 10, 0.3);
    color: var(--text-primary);
  }

  /* Focus Visible */
  :focus-visible {
    @apply outline-none ring-2 ring-primary/50 ring-offset-2;
    ring-offset-color: var(--background);
  }
}

/* ============================================
   COMPONENTS LAYER - Cards, Buttons, Layout
   ============================================ */
@layer components {
  /* Glass Card Effect */
  .glass-card {
    @apply relative overflow-hidden rounded-2xl border backdrop-blur-xl;
    background: rgba(var(--background-rgb), 0.6);
    border-color: var(--border);
  }

  /* Glass Card with Neon Border */
  .glass-card-neon {
    @apply glass-card;
    background: linear-gradient(135deg, rgba(213, 255, 10, 0.05), rgba(0, 193, 139, 0.05));
    border: 1px solid transparent;
    background-clip: padding-box;
  }

  .glass-card-neon::before {
    content: "";
    @apply absolute inset-0 rounded-2xl -z-10;
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-emerald) 100%);
    padding: 1px;
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
  }

  /* Subtle Glass Card */
  .glass-card-subtle {
    @apply relative overflow-hidden rounded-2xl backdrop-blur-lg;
    background: rgba(var(--background-rgb), 0.4);
    border: 1px solid var(--border-subtle);
  }

  /* Neon Button */
  .neon-button {
    @apply relative overflow-hidden rounded-lg border bg-transparent px-8 py-3 font-semibold transition-all;
    border-color: var(--color-primary);
    color: var(--color-primary);
    transition-duration: var(--duration-normal);
  }

  .neon-button:hover {
    @apply shadow-glow-primary;
    background: rgba(213, 255, 10, 0.1);
  }

  .neon-button::before {
    content: "";
    @apply absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-200%];
    transition: transform var(--duration-slower);
  }

  .neon-button:hover::before {
    @apply translate-x-[200%];
  }

  /* Container */
  .container-custom {
    @apply container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl;
  }

  /* Section */
  .section {
    @apply py-20 lg:py-32;
  }

  .section-sm {
    @apply py-12 lg:py-16;
  }

  .section-lg {
    @apply py-24 lg:py-40;
  }
}

/* ============================================
   UTILITIES LAYER - Text, Glow, Grids, Animations
   ============================================ */
@layer utilities {
  /* Text Gradients */
  .text-gradient-brand {
    @apply bg-gradient-brand bg-clip-text text-transparent;
  }

  .text-gradient-primary {
    @apply bg-gradient-primary bg-clip-text text-transparent;
  }

  .text-gradient-teal {
    @apply bg-gradient-teal bg-clip-text text-transparent;
  }

  /* Glow Effects */
  .glow-primary {
    box-shadow: var(--glow-primary-md);
  }

  .glow-primary-sm {
    box-shadow: var(--glow-primary-sm);
  }

  .glow-primary-lg {
    box-shadow: var(--glow-primary-lg);
  }

  .glow-green {
    box-shadow: var(--glow-green-md);
  }

  .glow-emerald {
    box-shadow: var(--glow-emerald-md);
  }

  .glow-teal {
    box-shadow: var(--glow-teal-md);
  }

  .glow-ocean {
    box-shadow: var(--glow-ocean-md);
  }

  /* Hover Glow */
  .hover-glow-primary {
    @apply transition-shadow;
    transition-duration: var(--duration-normal);
  }

  .hover-glow-primary:hover {
    box-shadow: var(--glow-primary-lg);
  }

  .hover-glow-emerald {
    @apply transition-shadow;
    transition-duration: var(--duration-normal);
  }

  .hover-glow-emerald:hover {
    box-shadow: var(--glow-emerald-lg);
  }

  /* Grid Layouts */
  .grid-albums {
    @apply grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8;
  }

  .grid-services {
    @apply grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8;
  }

  /* Glassmorphism */
  .glass-effect {
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }

  /* Avatar Morph Animation */
  .avatar-morph {
    animation: morph 8s ease-in-out infinite;
    border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
  }

  /* Glow Pulse */
  .glow-pulse {
    animation: glow-pulse 2s ease-in-out infinite;
  }

  /* Float Animation */
  .float {
    animation: float 3s ease-in-out infinite;
  }

  /* Shimmer Effect */
  .shimmer {
    animation: shimmer 2s linear infinite;
    background: linear-gradient(
      to right,
      transparent 0%,
      rgba(213, 255, 10, 0.2) 50%,
      transparent 100%
    );
    background-size: 1000px 100%;
  }

  /* Spin Slow */
  .spin-slow {
    animation: spin 20s linear infinite;
  }

  /* ============================================
     ADMIN UTILITY CLASSES
     ============================================ */

  /* Admin Background Effects */
  .admin-bg-gradient {
    background: var(--admin-bg);
    background-image: var(--gradient-admin-bg), var(--gradient-admin-bg-alt);
  }

  /* Admin Glass Effect */
  .admin-glass {
    background: var(--admin-surface);
    backdrop-filter: blur(var(--admin-blur-lg));
    -webkit-backdrop-filter: blur(var(--admin-blur-lg));
    border: 1px solid var(--admin-border);
  }

  .admin-glass-elevated {
    background: var(--admin-surface-elevated);
    backdrop-filter: blur(var(--admin-blur-xl));
    -webkit-backdrop-filter: blur(var(--admin-blur-xl));
    border: 1px solid var(--admin-border-strong);
  }

  /* Admin Glow Classes */
  .admin-glow-cyan {
    box-shadow: var(--admin-glow-cyan-md);
  }

  .admin-glow-lime {
    box-shadow: var(--admin-glow-lime-md);
  }

  .admin-glow-magenta {
    box-shadow: var(--admin-glow-magenta-md);
  }

  .admin-glow-purple {
    box-shadow: var(--admin-glow-purple-md);
  }

  /* Hover Glow Effects */
  .admin-hover-glow-cyan {
    transition: box-shadow var(--admin-transition-normal);
  }
  .admin-hover-glow-cyan:hover {
    box-shadow: var(--admin-glow-cyan-lg);
  }

  .admin-hover-glow-lime {
    transition: box-shadow var(--admin-transition-normal);
  }
  .admin-hover-glow-lime:hover {
    box-shadow: var(--admin-glow-lime-lg);
  }

  .admin-hover-glow-magenta {
    transition: box-shadow var(--admin-transition-normal);
  }
  .admin-hover-glow-magenta:hover {
    box-shadow: var(--admin-glow-magenta-lg);
  }

  .admin-hover-glow-purple {
    transition: box-shadow var(--admin-transition-normal);
  }
  .admin-hover-glow-purple:hover {
    box-shadow: var(--admin-glow-purple-lg);
  }

  /* Admin Card Styles */
  .admin-card {
    background: var(--gradient-admin-card);
    border: 1px solid var(--admin-border);
    border-radius: var(--radius-xl);
    transition: all var(--admin-transition-normal);
  }

  .admin-card:hover {
    background: var(--gradient-admin-card-hover);
    border-color: var(--admin-border-strong);
    transform: translateY(-2px);
    box-shadow: var(--admin-shadow-lg);
  }

  /* Admin Animations */
  .admin-shimmer {
    background: linear-gradient(
      90deg,
      var(--admin-surface) 0%,
      var(--admin-surface-elevated) 50%,
      var(--admin-surface) 100%
    );
    background-size: 200% 100%;
    animation: admin-shimmer 1.5s ease-in-out infinite;
  }

  .admin-pulse-cyan {
    animation: admin-pulse-cyan 2s ease-in-out infinite;
  }

  .admin-pulse-lime {
    animation: admin-pulse-lime 2s ease-in-out infinite;
  }

  .admin-pulse-magenta {
    animation: admin-pulse-magenta 2s ease-in-out infinite;
  }

  .admin-float {
    animation: admin-float 6s ease-in-out infinite;
  }

  /* Album descriptions custom styles */
  .album-descriptions p {
    @apply mb-4 last:mb-0;
  }

  .album-descriptions ul {
    @apply list-disc list-inside space-y-2 ml-4;
  }

  .album-descriptions li {
    color: var(--text-secondary);
  }

  .album-descriptions a {
    @apply text-neon-magenta hover:text-neon-purple hover:underline transition-colors;
  }

  .album-descriptions strong {
    color: var(--text-primary);
    @apply font-semibold;
  }

  .album-descriptions em {
    color: var(--color-primary);
    @apply font-medium;
  }

  .album-descriptions .tracklist-title {
    color: var(--text-primary);
    @apply font-bold mt-6 mb-3;
  }

  .album-descriptions .tracklist {
    @apply space-y-1;
  }

  /* Prose overrides for dark mode */
  .prose {
    --tw-prose-body: var(--text-secondary);
    --tw-prose-headings: var(--text-primary);
    --tw-prose-links: var(--color-emerald);
    --tw-prose-bold: var(--text-primary);
    --tw-prose-counters: var(--text-muted);
    --tw-prose-bullets: var(--color-primary);
    --tw-prose-hr: var(--border);
    --tw-prose-quotes: var(--text-secondary);
    --tw-prose-quote-borders: var(--color-primary);
    --tw-prose-captions: var(--text-muted);
    --tw-prose-code: var(--color-primary);
    --tw-prose-pre-code: var(--text-primary);
    --tw-prose-pre-bg: var(--surface);
    --tw-prose-th-borders: var(--border);
    --tw-prose-td-borders: var(--border-subtle);
  }
}

/* ============================================
   KEYFRAMES
   ============================================ */
@keyframes morph {
  0%,
  100% {
    border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
  }
  50% {
    border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%;
  }
}

@keyframes glow-pulse {
  0%,
  100% {
    box-shadow: 0 0 20px rgba(213, 255, 10, 0.5);
  }
  50% {
    box-shadow: 0 0 40px rgba(213, 255, 10, 1);
  }
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-20px);
  }
}

@keyframes shimmer {
  0% {
    background-position: -1000px 0;
  }
  100% {
    background-position: 1000px 0;
  }
}

/* ============================================
   ACCESSIBILITY - Reduced Motion
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  /* Preserve essential transforms but remove animations */
  .avatar-morph {
    animation: none;
  }

  .glow-pulse {
    animation: none;
  }

  .float {
    animation: none;
  }

  .shimmer {
    animation: none;
  }

  .spin-slow {
    animation: none;
  }
}

