@layer components {
  /* Glass Card Effect */
  .glass-card {
    @apply relative overflow-hidden rounded-2xl border border-white/10 bg-white/10 backdrop-blur-xl;
  }

  /* Glass Card with Gradient Border */
  .glass-card-neon {
    @apply glass-card;
    background: linear-gradient(135deg, rgba(0, 240, 255, 0.1), rgba(255, 0, 110, 0.1));
    border: 1px solid transparent;
    background-clip: padding-box;
  }

  .glass-card-neon::before {
    content: '';
    @apply absolute inset-0 rounded-2xl -z-10;
    background: linear-gradient(135deg, #00f0ff 0%, #ff006e 100%);
    padding: 1px;
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
  }

  /* Subtle Glass Card */
  .glass-card-subtle {
    @apply relative overflow-hidden rounded-2xl border border-white/5 bg-white/5 backdrop-blur-lg;
  }

  /* Neon Button */
  .neon-button {
    @apply relative overflow-hidden rounded-lg border border-neon-cyan bg-transparent px-8 py-3 font-semibold text-neon-cyan transition-all duration-300;
  }

  .neon-button:hover {
    @apply shadow-[0_0_20px_rgba(0,240,255,0.8)] bg-neon-cyan/10;
  }

  .neon-button::before {
    content: '';
    @apply absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent translate-x-[-200%] transition-transform duration-700;
  }

  .neon-button:hover::before {
    @apply translate-x-[200%];
  }

  /* Container */
  .container-custom {
    @apply container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl;
  }

  /* Section */
  .section {
    @apply py-20 lg:py-32;
  }
}

